    // ── Sigmoid activation (safe clamped) ──
    function sig(z) { return 1 / (1 + Math.exp(-Math.max(-30, Math.min(30, z)))); }

    // ── Full forward pass: 144 pixels -> probs ──
    function forwardPass(pixels) {
      // L1
      const a1 = new Float64Array(64);
      for (let j = 0; j < 64; j++) {
        let s = B1[j];
        for (let i = 0; i < 144; i++) s += W1[j][i] * pixels[i];
        a1[j] = sig(s);
      }
      // L2
      const a2 = new Float64Array(32);
      for (let k = 0; k < 32; k++) {
        let s = B2[k];
        for (let j = 0; j < 64; j++) s += W2[k][j] * a1[j];
        a2[k] = sig(s);
      }
      // L3 logits + softmax
      const logits = new Float64Array(10);
      let maxL = -Infinity;
      for (let m = 0; m < 10; m++) {
        let s = B3[m];
        for (let k = 0; k < 32; k++) s += W3[m][k] * a2[k];
        logits[m] = s;
        if (s > maxL) maxL = s;
      }
      const probs = new Float64Array(10);
      let sumE = 0;
      for (let m = 0; m < 10; m++) { probs[m] = Math.exp(logits[m] - maxL); sumE += probs[m]; }
      for (let m = 0; m < 10; m++) probs[m] /= sumE;

      return { pixels, a1, a2, probs, logits };
    }

    let state = forwardPass(new Float64Array(144));

